      private ->
         'enc_Privatebox'(element(2,Val), [<<161>>]);
      chan ->
         'enc_Streambox'(element(2,Val), [<<162>>]);
      mailbox ->
         'enc_Mailbox'(element(2,Val), [<<164>>]);
      group ->
         'enc_Groupbox'(element(2,Val), [<<168>>]);
      Else -> 
         exit({error,{asn1,{invalid_choice_type,Else}}})
   end,

encode_tags(TagIn, EncBytes, EncLen).




