   dec_MessageFeed(Tlv, []).

dec_MessageFeed(Tlv, TagIn) ->
Tlv1 = match_tags(Tlv, TagIn),
case (case Tlv1 of [CtempTlv1] -> CtempTlv1; _ -> Tlv1 end) of

%% 'private'
    {131073, V1} -> 
        {private, 'dec_Privatebox'(V1, [])};


%% 'chan'
    {131074, V1} -> 
        {chan, 'dec_Streambox'(V1, [])};


%% 'mailbox'
    {131076, V1} -> 
        {mailbox, 'dec_Mailbox'(V1, [])};


%% 'group'
    {131080, V1} -> 
        {group, 'dec_Groupbox'(V1, [])};

      Else -> 
         exit({error,{asn1,{invalid_choice_tag,Else}}})
   end
.


