dec_Conference(Tlv) ->
   dec_Conference(Tlv, [16]).

dec_Conference(Tlv, TagIn) ->
   %%-------------------------------------------------
   %% decode tag and length 
   %%-------------------------------------------------
Tlv1 = match_tags(Tlv, TagIn),

%%-------------------------------------------------
%% attribute id(1) with type OCTET STRING
%%-------------------------------------------------
[V1|Tlv2] = Tlv1, 
Term1 = decode_octet_string(V1, [4]),

%%-------------------------------------------------
%% attribute vsn(2) with type INTEGER
%%-------------------------------------------------
[V2|Tlv3] = Tlv2, 
Term2 = begin
Val1 = decode_integer(V2, [2]),
number2name(Val1, [{v0,0},{v1,1},{v2,2},{v3,3}])
end
,

%%-------------------------------------------------
%% attribute session(3) with type OCTET STRING
%%-------------------------------------------------
[V3|Tlv4] = Tlv3, 
Term3 = decode_octet_string(V3, [4]),

%%-------------------------------------------------
%% attribute name(4) with type OCTET STRING
%%-------------------------------------------------
[V4|Tlv5] = Tlv4, 
Term4 = decode_octet_string(V4, [4]),

%%-------------------------------------------------
%% attribute links(5) with type SEQUENCE OF
%%-------------------------------------------------
[V5|Tlv6] = Tlv5, 
Term5 = 'dec_Conference_links'(V5, [16]),

%%-------------------------------------------------
%% attribute description(6) with type OCTET STRING
%%-------------------------------------------------
[V6|Tlv7] = Tlv6, 
Term6 = decode_octet_string(V6, [4]),

%%-------------------------------------------------
%% attribute settings(7) with type SEQUENCE OF
%%-------------------------------------------------
[V7|Tlv8] = Tlv7, 
Term7 = 'dec_Conference_settings'(V7, [16]),

%%-------------------------------------------------
%% attribute members(8) with type SEQUENCE OF
%%-------------------------------------------------
[V8|Tlv9] = Tlv8, 
Term8 = 'dec_Conference_members'(V8, [16]),

%%-------------------------------------------------
%% attribute admins(9) with type SEQUENCE OF
%%-------------------------------------------------
[V9|Tlv10] = Tlv9, 
Term9 = 'dec_Conference_admins'(V9, [16]),

%%-------------------------------------------------
%% attribute data(10) with type SEQUENCE OF
%%-------------------------------------------------
[V10|Tlv11] = Tlv10, 
Term10 = 'dec_Conference_data'(V10, [16]),

%%-------------------------------------------------
%% attribute type(11) with type ENUMERATED
%%-------------------------------------------------
[V11|Tlv12] = Tlv11, 
Term11 = case decode_integer(V11, [10]) of
1 -> group;
2 -> channel;
3 -> call;
Default1 -> exit({error,{asn1,{illegal_enumerated,Default1}}})
end,

%%-------------------------------------------------
%% attribute tos(12) with type OCTET STRING
%%-------------------------------------------------
[V12|Tlv13] = Tlv12, 
Term12 = decode_octet_string(V12, [4]),

%%-------------------------------------------------
%% attribute unread(13) with type INTEGER
%%-------------------------------------------------
[V13|Tlv14] = Tlv13, 
Term13 = decode_integer(V13, [2]),

%%-------------------------------------------------
%% attribute mentions(14) with type SEQUENCE OF
%%-------------------------------------------------
[V14|Tlv15] = Tlv14, 
Term14 = 'dec_Conference_mentions'(V14, [16]),

%%-------------------------------------------------
%% attribute lastmsg(15)   External CHAT-v2:Message
%%-------------------------------------------------
[V15|Tlv16] = Tlv15, 
Term15 = 'dec_Message'(V15, [16]),

%%-------------------------------------------------
%% attribute update(16) with type INTEGER
%%-------------------------------------------------
[V16|Tlv17] = Tlv16, 
Term16 = decode_integer(V16, [2]),

%%-------------------------------------------------
%% attribute created(17) with type INTEGER
%%-------------------------------------------------
[V17|Tlv18] = Tlv17, 
Term17 = decode_integer(V17, [2]),

%%-------------------------------------------------
%% attribute status(18) with type ENUMERATED
%%-------------------------------------------------
[V18|Tlv19] = Tlv18, 
Term18 = case decode_integer(V18, [10]) of
1 -> create;
2 -> leave;
3 -> add;
4 -> remove;
5 -> removed;
6 -> join;
7 -> joined;
8 -> info;
9 -> patch;
10 -> get;
11 -> delete;
12 -> lastmsg;
13 -> mute;
14 -> unmute;
Default2 -> exit({error,{asn1,{illegal_enumerated,Default2}}})
end,

case Tlv19 of
[] -> true;_ -> exit({error,{asn1, {unexpected,Tlv19}}}) % extra fields not allowed
end,
Res1 = {'Conference',Term1,Term2,Term3,Term4,Term5,Term6,Term7,Term8,Term9,Term10,Term11,Term12,Term13,Term14,Term15,Term16,Term17,Term18},
Res1.
'dec_Conference_links'(Tlv, TagIn) ->
   %%-------------------------------------------------
   %% decode tag and length 
   %%-------------------------------------------------
Tlv1 = match_tags(Tlv, TagIn),
[decode_octet_string(V1, [4]) || V1 <- Tlv1].


'dec_Conference_settings'(Tlv, TagIn) ->
   %%-------------------------------------------------
   %% decode tag and length 
   %%-------------------------------------------------
Tlv1 = match_tags(Tlv, TagIn),
['dec_Feature'(V1, [16]) || V1 <- Tlv1].


'dec_Conference_members'(Tlv, TagIn) ->
   %%-------------------------------------------------
   %% decode tag and length 
   %%-------------------------------------------------
Tlv1 = match_tags(Tlv, TagIn),
['dec_Member'(V1, [16]) || V1 <- Tlv1].


'dec_Conference_admins'(Tlv, TagIn) ->
