%%================================
%%  CHATProtocol
%%================================
enc_CHATProtocol(Val) ->
    enc_CHATProtocol(Val, []).

enc_CHATProtocol(Val, TagIn) ->
   {EncBytes,EncLen} = case element(1,Val) of
      authority ->
         'enc_Authority'(element(2,Val), [<<161>>]);
      message ->
         'enc_Message'(element(2,Val), [<<162>>]);
      inbox ->
         'enc_Inbox'(element(2,Val), [<<163>>]);
      ack ->
         'enc_Ack'(element(2,Val), [<<164>>]);
      activity ->
         'enc_Activity'(element(2,Val), [<<165>>]);
      subscription ->
         'enc_Subscription'(element(2,Val), [<<166>>]);
      search ->
         'enc_Search'(element(2,Val), [<<167>>]);
      roster ->
         'enc_Roster'(element(2,Val), [<<168>>]);
      conference ->
         'enc_Conference'(element(2,Val), [<<169>>]);
      Else -> 
         exit({error,{asn1,{invalid_choice_type,Else}}})
   end,

encode_tags(TagIn, EncBytes, EncLen).




dec_CHATProtocol(Tlv) ->
   dec_CHATProtocol(Tlv, []).

dec_CHATProtocol(Tlv, TagIn) ->
Tlv1 = match_tags(Tlv, TagIn),
case (case Tlv1 of [CtempTlv1] -> CtempTlv1; _ -> Tlv1 end) of

%% 'authority'
    {131073, V1} -> 
        {authority, 'dec_Authority'(V1, [])};


%% 'message'
    {131074, V1} -> 
        {message, 'dec_Message'(V1, [])};


%% 'inbox'
    {131075, V1} -> 
        {inbox, 'dec_Inbox'(V1, [])};


%% 'ack'
    {131076, V1} -> 
        {ack, 'dec_Ack'(V1, [])};


%% 'activity'
    {131077, V1} -> 
        {activity, 'dec_Activity'(V1, [])};


%% 'subscription'
    {131078, V1} -> 
        {subscription, 'dec_Subscription'(V1, [])};


%% 'search'
    {131079, V1} -> 
        {search, 'dec_Search'(V1, [])};


%% 'roster'
    {131080, V1} -> 
        {roster, 'dec_Roster'(V1, [])};


%% 'conference'
    {131081, V1} -> 
        {conference, 'dec_Conference'(V1, [])};

      Else -> 
         exit({error,{asn1,{invalid_choice_tag,Else}}})
   end
.


